import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array, status: string }} invoice
 * @returns {string} plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const header = invoice.number ?? 'DRAFT';

  const lines = invoice.lines.map((line) => {
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const lineTotal = line.qty * line.unitPrice;
    const lineTotalFormatted = formatEuros(lineTotal);
    return `${line.qty} x ${line.name} @ ${unitPriceFormatted} = ${lineTotalFormatted}`;
  });

  const totals = invoiceTotals(invoice);
  const totalFormatted = formatEuros(totals.total);

  const parts = [header, customerName, ...lines, `Total: ${totalFormatted}`];
  return parts.join('\n');
}

